function article(row: Editorial, category: string): Post {
  const [slug, title, excerpt, html, source, url] = row;
  return { slug, date: '2026-10-11', category, title: { tr: title }, excerpt: { tr: excerpt }, body: { tr: `${html}${fieldNotes[slug] ? `<h2>Saha notu</h2><p>${fieldNotes[slug]}</p>` : ''}<h2>Kaynak ve devam okuması</h2><p>Teknik başvuru: <a href="${url}" target="_blank" rel="noopener noreferrer">${source}</a>. Kaynak kontrolü: 11 Ekim 2026. Uygulama senaryoları IPScans için hazırlanmış örneklerdir; ölçülmüş ürün performansı veya kurumunuza özgü doğrulama sonucu değildir.</p><p>Temel kavramları pekiştirmek için <a href="/tr/blog/ip-adresi-nedir">IP adreslerinin çalışma biçimini</a> ve <a href="/tr/blog/ag-bakim-kontrol-listesi">ağ bakım kontrol listesini</a> inceleyin.</p>` } };
}

export const infinityOperations: Post[] = [
  ...security.map(row => article(row, 'Siber Güvenlik ve Ağ Güvenliği')),
  ...infrastructure.map(row => article(row, 'Router, Switch ve Access Point')),
];
